# sanitize-transcript.jq --- Regras canonicas de higienizacao da transcricao de sessao.
#
# Aplicado por 'scripts/export-session' a cada linha (objeto JSON) do JSONL bruto do
# Claude Code. Preserva os prompts, o texto do assistente, o raciocinio ('thinking') e as
# chamadas de ferramenta como nome mais argumentos de entrada. Descarta ou trunca as
# superficies onde se concentra o risco de exposicao de segredos: as saidas de ferramenta
# (campo 'toolUseResult' e blocos 'tool_result'), os anexos, os snapshots de arquivo e o
# conteudo das mensagens de sistema.

# Reescreve um bloco de conteudo de mensagem preservando apenas os campos de baixo risco.
def scrub_block:
  if type != "object" then "[block stripped]"
  elif .type == "text" then {type, text}
  elif .type == "thinking" then {type, thinking}
  elif .type == "tool_use" then {type, id, name, input}
  elif .type == "tool_result" then {type, tool_use_id, content: "[tool output stripped]"}
  elif .type == "image" then {type, source: "[image stripped]"}
  else {type, note: "[block stripped]"}
  end;

# Higieniza o corpo de uma mensagem 'user' ou 'assistant'. Um conteudo em cadeia e um
# prompt e e preservado; um conteudo em arranjo tem cada bloco reescrito por 'scrub_block'.
def scrub_message:
  if .content == null then .
  elif (.content | type) == "array" then .content |= map(scrub_block)
  else .
  end;

if .type == "user" or .type == "assistant" then
  del(.toolUseResult) | (.message |= scrub_message)
elif .type == "attachment" then
  {type, uuid, parentUuid, timestamp, sessionId, attachment: "[attachment stripped]"}
elif .type == "file-history-snapshot" then
  {type, messageId, snapshot: "[snapshot stripped]"}
elif .type == "system" then
  {type, subtype, level, uuid, parentUuid, timestamp, sessionId,
   content: "[system content stripped]"}
else .
end

